const context = $input.first().json;

const prompt = `You are an elite endurance coach. It is Sunday evening.
Today's Date: ${new Date().toISOString().split('T')[0]}

### ATHLETE CONTEXT
Coach Notes: ${context.coach_notes}
Current Phase Strategy: ${JSON.stringify(context.strategy || "No active strategy")}

### PAST WEEK VOLUME
${JSON.stringify(context.week_volume || "No activities recorded.")}

### INSTRUCTIONS
CRITICAL RULES:
1. Keep your conversational response extremely short and concise (under 150 words). Do not write long essays.
2. Based on the "Current Phase Strategy", you MUST generate specific daily workouts for the immediate upcoming 7 days (Monday through Sunday) starting from tomorrow.
3. You MUST output the upcoming workouts EXACTLY in this JSON format wrapped in \`\`\`json markdown blocks:

\`\`\`json
{
  "new_workouts": [
    {"scheduled_date": "YYYY-MM-DD", "sport_type": "Run", "title": "Base Run", "description": "...", "target_duration_mins": 45}
  ]
}
\`\`\`
`;

return {
    systemPrompt: prompt,
    telegramId: context.telegram_id
};

const response = $input.first().json.text;
let text = response;
let workouts = [];

let match = response.match(/```(?:json)?\s*([\s\S]*?)\s*```/);
if (!match) {
    match = response.match(/(\{[\s\S]*"new_workouts"[\s\S]*\})/);
}

if (match) {
    try {
        const parsed = JSON.parse(match[1]);
        if (parsed.new_workouts) {
            workouts = parsed.new_workouts;
            text = text.replace(match[0], ''); // Clean text for Telegram
        }
    } catch (e) {}
}

let finalReply = text.trim();
if (finalReply.length > 4000) {
    finalReply = finalReply.substring(0, 4000) + '\n\n...[Message truncated by AI Coach]';
}

// Return one item containing the text, and split the workouts into separate items for the Postgres node
return {
    replyText: finalReply,
    workouts: workouts,
    athleteId: $('Loop Over Items').item.json.id,
    telegramId: $('Postgres Fetch Weekly').item.json.telegram_id
};

