VALUES (
    '{{ $json.athleteId }}',
    '{{ $json.scheduled_date }}',
    '{{ $json.sport_type }}',
    '{{ $json.title }}',
    $$ {{ $json.description }} $$,
    {{ $json.target_duration_mins }}
)
RETURNING id AS workout_db_id, athlete_id, scheduled_date, sport_type, title, description, target_duration_mins;

