const athleteId = $input.first().json.athleteId;

return workouts.map(workout => {
    return {
        json: {
            athleteId: athleteId,
            scheduled_date: workout.scheduled_date || new Date().toISOString().split('T')[0],
            sport_type: workout.sport_type || 'Run',
            title: workout.title || workout.sport_type || 'Workout',
            description: workout.description || 'Workout planned by AI Coach',
            target_duration_mins: workout.target_duration_mins || 60
        }
    };
});
